package de.lazytv.pro.catalog; public final class CatalogItems { private CatalogItems(){} public static StreamItem create(String id,String name,String category,String logo,String url,String tvg,CatalogType type){switch(type){case LIVE:return new Channel(id,name,category,logo,url,tvg);case MOVIES:return new Movie(id,name,category,logo,url,tvg);case SERIES:return new Series(id,name,category,logo,url,tvg);default:return new StreamItem(id,name,category,logo,url,tvg,type);}}}